-- First authored level-1 areas; these count toward the ten PvE locations per world.
-- Descriptions are game adaptations, not quotations or a later-war quest chronology.
INSERT INTO locations(planet_id,code,name,description,position,recommended_level)
SELECT p.id,v.code,v.name,v.description,1,1 FROM (VALUES
 ('coruscant','lower_residential_levels','Нижние жилые уровни','Жилые переходы и тесные переулки под сияющими башнями столицы. Здесь повседневная жизнь мегаполиса соседствует с опасностями нижних уровней.'),
 ('dromund_kaas','kaas_city_outskirts','Окраины Каас-Сити','Дороги у границы имперской столицы уходят под густые кроны джунглей. За освещёнными постами начинаются заросли и влажные ущелья.'),
 ('tython','forest_trails','Лесные тропы','Тропы пересекают зелёные склоны Тайтона и теряются среди древних камней. Вдали от исследовательских стоянок природа быстро скрывает следы путников.'),
 ('korriban','valley_approach','Подступы к Долине Тёмных Лордов','Красная пыль покрывает каменистые тропы к древним гробницам. Между скалами лежат обломки монументов и следы множества прежних экспедиций.')
) AS v(planet_code,code,name,description) JOIN planets p ON p.code=v.planet_code
ON CONFLICT (planet_id,code) DO NOTHING;

-- Capital PvE areas: authored districts/landscapes inspired by the Holonet,
-- without importing the later sack of Coruscant or SWTOR quest events.
INSERT INTO locations(planet_id,code,name,description,position,recommended_level)
SELECT p.id,v.code,v.name,v.description,v.position,v.recommended_level FROM (VALUES
 ('coruscant','service_walkways','Служебные переходы','Под жилыми башнями тянутся узкие галереи обслуживания. Свет ремонтных ламп теряется среди труб, кабелей и закрытых технических дверей.',2,6),
 ('coruscant','freight_docks','Грузовые доки','Транспортные платформы принимают припасы со всей Республики. За рядами контейнеров начинаются складские коридоры, куда редко заглядывают портовые инспекторы.',3,11),
 ('coruscant','workshop_quarter','Квартал мастерских','В тесных ангарах разбирают спидеры и восстанавливают дроидов. Переулки между мастерскими заполнены запчастями, дымом и гулом работающих станков.',4,16),
 ('coruscant','lower_markets','Нижние рынки','Многоярусные торговые ряды скрыты под перекрытиями старых кварталов. Легальные лавки соседствуют с запертыми складами и неприметными проходами для тайных сделок.',5,21),
 ('coruscant','abandoned_factories','Заброшенные фабрики','Промышленный сектор давно уступил место новым производствам. В огромных цехах остались остановленные конвейеры, отключённые дроиды и тёмные шахты грузовых лифтов.',6,26),
 ('coruscant','transit_tunnels','Транспортные тоннели','Старые транспортные линии уходят далеко под действующие магистрали. На развилках рельсы исчезают в темноте, а грохот города доносится сквозь толщу перекрытий.',7,31),
 ('coruscant','power_sublevels','Энергетические подуровни','В глубине городских ярусов работают распределительные станции. Узкие мостки проходят над силовыми магистралями, и каждый неисправный узел грозит оставить целый район без света.',8,36),
 ('coruscant','sealed_sectors','Закрытые сектора','Опечатанные жилые блоки отделены от города тяжёлыми переборками. За ними сохранились целые улицы прежних эпох, исчезнувшие с большинства современных схем.',9,41),
 ('coruscant','deep_underlevels','Глубины нижнего города','На самых глубоких доступных ярусах не видно дневного света. Слои древней застройки образуют запутанный лабиринт, в котором привычные городские ориентиры теряют смысл.',10,46),
 ('dromund_kaas','jungle_road','Джунглевая дорога','Разбитая дорога петляет между корнями исполинских деревьев. Грозовые тучи скрывают небо, а за пределами редких сторожевых постов начинается непроглядная чаща.',2,6),
 ('dromund_kaas','supply_outpost','Снабженческий форпост','У укреплённой площадки сходятся пути военных грузов. Склады и посадочные маяки окружены джунглями, которые приходится постоянно оттеснять от периметра.',3,11),
 ('dromund_kaas','quarry_trails','Тропы каменоломен','Следы тяжёлых машин ведут к старым выработкам. Между отвесными стенами лежат брошенные подъёмники, а дождевые потоки превращают нижние площадки в глубокие водоёмы.',4,16),
 ('dromund_kaas','storm_marshes','Грозовые топи','Чёрная вода заполняет низины под густыми кронами. Вспышки молний на мгновение освещают островки твёрдой земли и остатки провалившихся в болото построек.',5,21),
 ('dromund_kaas','forgotten_ruins','Забытые руины','Джунгли поглотили каменные сооружения древних поселенцев. Из земли выступают расколотые колонны, а спуски под развалины скрыты корнями и влажным мхом.',6,26),
 ('dromund_kaas','shadow_gorges','Теневые ущелья','Глубокие разломы пересекают лесистые склоны. Внизу шумят подземные потоки, и немногочисленные переходы над пропастями давно остались без присмотра.',7,31),
 ('dromund_kaas','ancient_catacombs','Древние катакомбы','Каменные лестницы уходят под основания давно исчезнувших зданий. В тесных проходах сохранились потускневшие знаки ситхов и тяжёлые двери погребальных камер.',8,36),
 ('dromund_kaas','ritual_grounds','Ритуальные площадки','На скальных уступах среди джунглей стоят древние монолиты. Грозы не стихают над истёртыми кругами камня, и даже привычный шум леса здесь звучит приглушённо.',9,41),
 ('dromund_kaas','sealed_sanctum','Запечатанное святилище','Массивные стены скрывают святилище одной из забытых эпох ситхов. За повреждёнными печатями лежат глубокие залы, отделённые от внешнего мира веками запустения.',10,46)
) AS v(planet_code,code,name,description,position,recommended_level) JOIN planets p ON p.code=v.planet_code
ON CONFLICT (planet_id,code) DO NOTHING;

-- Ancient sites and authored wilderness areas; no later SWTOR class-story events.
-- Tython's main Jedi Temple has not yet relocated from Coruscant in our era.
INSERT INTO locations(planet_id,code,name,description,position,recommended_level)
SELECT p.id,v.code,v.name,v.description,v.position,v.recommended_level FROM (VALUES
 ('tython','misty_slopes','Туманные склоны','Утренний туман скрывает каменные уступы над лесом. Между валунами петляют звериные тропы, а на мягкой земле заметны следы недавних стоянок.',2,6),
 ('tython','river_gorges','Речные теснины','Быстрые потоки прорезают зелёные склоны и сходятся в узких ущельях. Перейти на другой берег можно по скользким камням и остаткам древних мостов.',3,11),
 ('tython','woodland_ravine','Лесные ущелья','Кроны смыкаются над глубокими оврагами. Среди корней скрыты проходы к небольшим лагерям, откуда хорошо видны тропы исследователей.',4,16),
 ('tython','kaleth_approach','Подступы к Калету','Лес расступается перед разрушенными стенами Калета. Из травы выступают обломки статуй, а за поваленными колоннами темнеют входы в древние залы.',5,21),
 ('tython','lower_kaleth','Нижние руины Калета','Каменные лестницы соединяют заросшие дворы древнего города. Под грудами обломков сохранились коридоры, по которым всё ещё движутся старые боевые машины.',6,26),
 ('tython','upper_kaleth','Верхние руины Калета','На высоких террасах стоят остатки массивных сооружений. Узкие переходы между ними открыты ветру, а пробудившиеся дроиды охраняют давно опустевшие площадки.',7,31),
 ('tython','mountain_pass','Горный перевал','Крутая тропа поднимается выше лесной границы. Ветер гуляет между скалами, и за каждым поворотом открывается новый участок древнего пути через горы.',8,36),
 ('tython','forge_approach','Тропа к Кузнице','За перевалом лежат каменные площадки и разрушенные опоры старой дороги. Уцелевшие проходы ведут к древней Кузнице, скрытой среди гор.',9,41),
 ('tython','ancient_forge','Древняя Кузница','Древнее сооружение хранит следы мастеров давно ушедшей эпохи. Под открытым небом сохранились рабочие площадки и механизмы, охраняемые уцелевшими стражами.',10,46),
 ('korriban','red_dunes','Красные пески','Пыльные ветры гонят песок между выветренными скалами. Останки экспедиций и брошенные ящики снабжения исчезают под наносами, привлекая местных хищников.',2,6),
 ('korriban','rock_passes','Скальные проходы','Тесные расселины соединяют пустоши с погребальной долиной. На отвесных стенах сохранились стёртые знаки, а в тени камней прячутся звери.',3,11),
 ('korriban','shyrack_caves','Пещеры шираков','Под каменными сводами гнездятся шираки. Их крики отражаются от стен, заглушая шаги, а узкие боковые ходы уходят глубоко под поверхность.',4,16),
 ('korriban','ruined_crypts','Разрушенные склепы','Обрушившиеся погребальные камеры открыты пустынному ветру. Между расколотыми саркофагами лежат следы разграбления и остатки старых охранных механизмов.',5,21),
 ('korriban','abandoned_excavation','Заброшенные раскопки','Вокруг вскрытых древних стен стоят опустевшие навесы археологов. Оборудование покрыто пылью, но свежие следы показывают, что поиски реликвий здесь продолжаются.',6,26),
 ('korriban','ajunta_pall_tomb','Гробница Аджанты Палла','Каменные коридоры ведут в древнюю гробницу одного из первых Тёмных Лордов. За повреждёнными дверями скрываются погребальные залы и норы местных существ.',7,31),
 ('korriban','tulak_hord_tomb','Гробница Тулака Хорда','Массивные стены окружают залы, посвящённые древнему владыке ситхов. Следы искателей реликвий теряются у закрытых переходов и осыпавшихся лестниц.',8,36),
 ('korriban','marka_ragnos_tomb','Гробница Марки Рагноса','Тяжёлые ступени поднимаются к погребальному комплексу древнего правителя. В тёмных залах сохранились монументы его власти, привлекающие исследователей и тайные культы.',9,41),
 ('korriban','naga_sadow_tomb','Гробница Наги Садоу','За монументальным входом простирается лабиринт древних камер. Не все печати вскрыты, и каждый новый проход обещает находку тем, кто решится потревожить его стражей.',10,46)
) AS v(planet_code,code,name,description,position,recommended_level) JOIN planets p ON p.code=v.planet_code
ON CONFLICT (planet_id,code) DO NOTHING;
